import { mountScoutingBook } from './scouting-book.mjs';
import { openNotebookPopup } from "./notebook-popup.mjs";
export async function mountDetectiveDesk(container,{assets,resolveFile,serviceSnapshot,investigate,scout,initialKind="investigate",initialTarget="",onClose=()=>{},onChanged=()=>{},portraitFile,scoutingUploadImage,scoutingImageSelection}){
  if(initialKind==='scout')return mountScoutingBook(container,{assets,resolveFile,serviceSnapshot,scout,onChanged,onClose,portraitFile,uploadImage:scoutingUploadImage,imageSelection:scoutingImageSelection});
  const doc=container.ownerDocument,win=doc.defaultView,root=doc.createElement('section');root.className='dd-window';root.setAttribute('role','dialog');root.setAttribute('aria-label','林安的委托柜台');
  const style=doc.createElement('style');style.textContent=`.dd-window{pointer-events:auto;position:absolute;inset:0;overflow:hidden;background:#19140feb;color:#57432d;font-family:"Songti SC",serif}.dd-window *{box-sizing:border-box}.dd-panel{position:absolute;width:1040px;height:610px;transform-origin:top left;padding:34px 42px;background:linear-gradient(135deg,#f4e9d4,#e6d5b3);border:1px solid #a58a60;border-radius:7px;box-shadow:0 14px 65px #0007}.dd-header{display:flex;align-items:center;gap:28px}.dd-header h2{font-weight:500;font-size:32px;margin:0}.dd-money{margin-left:auto;font:26px Georgia,serif}.dd-panel button{font:25px "Songti SC",serif;cursor:pointer;color:inherit;border:0;background:none;min-height:50px}.dd-panel button:disabled{opacity:.4;cursor:default}.dd-close{width:68px}.dd-job{position:absolute;left:42px;top:115px;width:950px;height:133px;padding:20px 24px;border:1px solid #b2986a66;background:#c3ac7e15;border-radius:5px}.dd-job strong{font-size:28px;font-weight:500}.dd-job small{font-size:22px;float:right;color:#967651}.dd-progress{height:11px;background:#ac916533;margin:20px 0 12px;border-radius:5px;overflow:hidden}.dd-progress i{display:block;height:100%;background:#8b6d46;border-radius:5px}.dd-job p{margin:0;font-size:22px;color:#876c49}.dd-controls{position:absolute;left:42px;top:265px;display:flex;align-items:center;gap:24px}.dd-controls button{font-size:25px;border-bottom:2px solid transparent}.dd-controls button[aria-pressed=true]{border-color:#9b6559;color:#8b4d43}.dd-controls input{width:365px;padding:9px 14px;border:1px solid #b2986977;background:#f8f0df;font:23px "Songti SC",serif;color:#5b442d}.dd-list{position:absolute;left:42px;top:337px;right:42px;height:205px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px;align-content:start;overflow-y:auto;scrollbar-width:thin}.dd-case{border:1px solid #b4997166;border-radius:4px;min-height:89px;display:flex;align-items:center;padding:10px 15px;gap:12px;background:#fff7e820}.dd-case .dd-name{font-size:23px;flex:1;min-width:0;text-align:left;border:0;background:none}.dd-case .dd-photo{width:60px;min-width:60px;height:68px;padding:0;border:0;background:none}.dd-photo img{width:100%;height:100%;object-fit:cover;border-radius:3px}.dd-case button{border:1px solid #a98c5d77;min-width:160px;border-radius:4px;font-size:23px;background:#c6ad7c22}.dd-error{position:absolute;bottom:23px;left:44px;font-size:23px;color:#9a5045}.dd-case.empty{font-size:25px;color:#987f5c;grid-column:1/-1}.dd-panel button:focus-visible,.dd-controls input:focus-visible{outline:2px solid #a26b51;outline-offset:2px}`;
  root.innerHTML='<div class="dd-panel"><header class="dd-header"><h2>林安的委托柜台</h2><span class="dd-money"></span><button class="dd-close" aria-label="关闭委托柜台">×</button></header><section class="dd-job" aria-live="polite"></section><div class="dd-controls"><button data-kind="investigate" aria-pressed="true">调查档案</button><input type="search" aria-label="搜索委托对象" placeholder="搜索人物"></div><div class="dd-list"></div><div class="dd-error" role="status"></div></div>';
  root.prepend(style);container.append(root);let state=null,kind=initialKind==='scout'?'scout':'investigate',query='',busy=false,destroyed=false;
  const panel=root.querySelector('.dd-panel'),error=root.querySelector('.dd-error');
  function fit(){const scale=Math.min(container.clientWidth/1090,container.clientHeight/650);panel.style.left=`${(container.clientWidth-1040*scale)/2}px`;panel.style.top=`${(container.clientHeight-610*scale)/2}px`;panel.style.transform=`scale(${scale})`;}
  function render(){
    root.querySelector('.dd-money').textContent=state.balance==null?'现金未就绪':'¥ '+state.balance.toLocaleString();
    const job=root.querySelector('.dd-job');job.replaceChildren();const title=doc.createElement('strong'),note=doc.createElement('small'),bar=doc.createElement('div'),fill=doc.createElement('i'),text=doc.createElement('p');bar.className='dd-progress';bar.append(fill);
    if(state.active){title.textContent=(state.active.kind==='scout'?'物色':'调查')+' · '+state.active.targetName;note.textContent=state.active.days+'天 / '+Math.floor(state.active.progress*100)+'%';fill.style.width=state.active.progress*100+'%';text.textContent='林安正在工作。';}
    else{title.textContent=state.last?'已交付 · '+state.last.targetName:'林安在事务所';note.textContent=state.accessReason?'此处可查看委托':'可以受理新委托';fill.style.width=state.last?'100%':'0%';text.textContent=state.last?(state.last.kind==='scout'?'人物已加入管理库，可另行委托调查。':'调查完成，档案已解密。'):'物色和调查分别收费，每次预计七至十四天。';}if(state.accessReason)text.textContent=state.accessReason;job.append(title,note,bar,text);
    const list=root.querySelector('.dd-list');list.replaceChildren();const rows=(kind==='scout'?state.candidates:state.characters).filter(x=>!query||x.name.includes(query));
    for(const row of rows){const card=doc.createElement('article');card.className='dd-case';const label=doc.createElement('button');label.className='dd-name';label.textContent=row.name;const photo=doc.createElement('button');photo.className='dd-photo';photo.setAttribute('aria-label','查看'+row.name+'的简要信息');if(row.portrait){const img=doc.createElement('img');img.src=row.portrait;img.alt=row.name;photo.append(img);}else photo.textContent=row.name.slice(-1);const details=()=>{const info=row.info??{};const dialog=openNotebookPopup(root,row.name,[{title:'简要资料',details:[info.gender?String(info.gender):'',Number.isFinite(Number(info.age))?'年龄：'+info.age:'',info.identity?String(info.identity):''].filter(Boolean)}]);if(row.portrait){const img=doc.createElement('img');img.src=row.portrait;img.alt=row.name;img.style.cssText='width:120px;height:160px;object-fit:contain;float:right;margin:0 0 16px 20px';dialog.querySelector('.np-card').prepend(img);}};photo.addEventListener('click',details);label.addEventListener('click',details);const button=doc.createElement('button');const price=state.prices[row.id]?.[kind];button.type='button';button.textContent=kind==='investigate'&&row.investigationAllowed===false?'调查未开放':kind==='investigate'&&row.unlocked?'已解密':row.scoutingPending?'物色中':(kind==='scout'?'物色':'调查')+' ¥'+price;button.title=row.permissionReason??'';button.disabled=state.writable===false||kind==='investigate'&&row.investigationAllowed===false||busy||Boolean(state.active)||state.balance==null||state.balance<price||row.scoutingPending||kind==='investigate'&&row.unlocked;button.setAttribute('aria-label',(kind==='scout'?'物色':'调查')+row.name+'，'+price+'日元');button.addEventListener('click',async()=>{if(busy)return;busy=true;render();error.textContent='';try{await(kind==='scout'?scout(row.id):investigate(row.id));await refresh();await onChanged();}catch(e){error.textContent=e.message;}finally{busy=false;render();}});card.append(photo,label,button);list.append(card);}
    if(!rows.length){const empty=doc.createElement('div');empty.className='dd-case empty';empty.textContent=kind==='scout'?'当前角色库中没有尚未物色的人物。':'没有匹配的人物。';list.append(empty);}
  }
  async function refresh(){try{const next=await serviceSnapshot();if(destroyed)return;state=next;render();}catch(e){if(!destroyed)error.textContent=e.message;}}
  root.querySelectorAll('[data-kind]').forEach(button=>button.addEventListener('click',()=>{kind=button.dataset.kind;root.querySelectorAll('[data-kind]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));render();}));root.querySelector('input').addEventListener('input',e=>{query=e.target.value.trim();render();});root.querySelector('.dd-close').addEventListener('click',onClose);root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();onClose();}});
  fit();await refresh(); if (initialTarget) { const row = (kind === "scout" ? state.candidates : state.characters).find(x => x.id === initialTarget); if (row) { query = row.name; root.querySelector("input").value = query; render(); } } root.querySelectorAll("[data-kind]").forEach(button => button.setAttribute("aria-pressed", String(button.dataset.kind === kind))); win.addEventListener('resize',fit);const timer=win.setInterval(refresh,2000);return{root,refresh,destroy(){destroyed=true;win.clearInterval(timer);win.removeEventListener('resize',fit);root.remove();}};
}
